    private function do_fetch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches all historical $orders for the user
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-$wallet-prediction-trading/api/rest-api/trade#query-order-history
         *
         * @param {string} [$outcome] filter by $outcome
         * @param {int} [$since] only return $orders updated $since this timestamp in ms
         * @param {int} [$limit] max number of $orders to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->orderType] Filter by order type. Enum => MARKET, LIMIT
         * @param {string} [$params->l1Category] Filter by level-1 category
         * @param {string} [$params->status] Filter by order status
         * @param {string} [$params->until] end timestamp in ms
         * @param {boolean} [$params->paginate] *spot only* default false, when true will automatically $paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-$params)
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        $paginate = false;
        list($paginate, $params) = $this->handle_option_and_params($params, 'fetchOrders', 'paginate');
        $maxEntriesPerRequest = null;
        list($maxEntriesPerRequest, $params) = $this->handle_option_and_params($params, 'fetchOrders', 'maxEntriesPerRequest', 100);
        $pageKey = 'ccxtPageKey';
        if ($paginate) {
            return Async\await($this->fetch_paginated_call_incremental('fetchOrders', $outcome, $since, $limit, $params, $pageKey, $maxEntriesPerRequest));
        }
        $page = $this->safe_integer($params, $pageKey, 1) - 1;
        $request = array();
        $offSet = $this->safe_integer($params, 'offset', $page * $maxEntriesPerRequest);
        if ($offSet > 0) {
            $request['offset'] = $offSet;
        }
        $outcomeObj = null;
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
        }
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        if ($since !== null) {
            $request['startDate'] = $this->yyyymmdd($since);
        }
        $until = $this->safe_integer($params, 'until');
        $params = $this->omit($params, 'until');
        if ($until !== null) {
            $request['endDate'] = $this->yyyymmdd($until);
        }
        $wallet = Async\await($this->fetch_wallet('fetchOrders', $params));
        $request['walletAddress'] = $wallet['walletAddress'];
        $response = Async\await($this->sapiPrivateGetOrderHistory($this->extend($request, $params)));
        //
        // {
        //     "total" => 15,
        //     "offset" => 0,
        //     "limit" => 20,
        //     "orders" => array(
        //         {
        //             "orderId" => "54100",
        //             "vendorOrderId" => "0xabcd5678...",
        //             "vendor" => "PREDICT_FUN",
        //             "marketTopicId" => 4229500,
        //             "slug" => "btc-price-1h-up-or-down-prev",
        //             "marketTopicTitle" => "BTC Price 1h Up or Down?",
        //             "marketId" => 5567800,
        //             "marketTitle" => "UP",
        //             "outcome" => "YES",
        //             "outcomeIndex" => 0,
        //             "status" => "CLOSED",
        //             "side" => "BUY",
        //             "orderType" => "MARKET",
        //             "createTime" => 1748045100000,
        //             "modifyTime" => 1748045101000,
        //             "terminalTime" => 1748045101000,
        //             "makerUsdtAmount" => "1.00",
        //             "makerShareQty" => "1923.07",
        //             "filledUsdtAmount" => "1.00",
        //             "filledShareQty" => "1923.07",
        //             "fillPercentage" => "1.00",
        //             "price" => "0.52",
        //             "marketProviderFee" => "0.02",
        //             "networkFee" => "0.000001"
        //         }
        //     )
        // }
        //
        $orders = $this->safe_list($response, 'orders', array());
        $parsedOrders = $this->parse_prediction_orders($orders, $outcomeObj, $since);
        return $this->filter_by_outcome_since_limit($parsedOrders, $outcome, $since, $limit);
    }

    public function fetch_positions(?array $outcomes = null, $params = array()): PromiseInterface {
