    private function do_fetch_positions(?array $outcomes = null, $params = array()) {
        /**
         * fetches the user's outcome $positions; outcome $positions are spot token balances under the "+<encoding>" coin form (size and entry notional), the value/entry/mark price/pnl are computed from the current mid prices
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-$wallet-prediction-trading/api/rest-api/position#query-$positions
         *
         * @param {string[]} [$outcomes] filter by outcome ids or $outcomes
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->tab] Position status tab. Values from PositionQueryType. Default ONGOING
         * @return {array[]} a list of [prediction $position structures](https://docs.ccxt.com/#/?id=prediction-$position-structure)
         */
        Async\await($this->load_outcomes());
        $requestedOutcomeSymbols = array();
        if ($outcomes !== null) {
            for ($i = 0; $i < count($outcomes); $i++) {
                $requested = $outcomes[$i];
                $requestedOutcomeObj = $this->safe_outcome($requested);
                $requestedOutcome = $this->safe_string($requestedOutcomeObj, 'outcome', $requested);
                $requestedOutcomeSymbols[$requestedOutcome] = true;
            }
        }
        $wallet = Async\await($this->fetch_wallet('fetchPositions', $params));
        $request = array(
            'walletAddress' => $wallet['walletAddress'],
        );
        $response = Async\await($this->sapiPrivateGetPositionList($this->extend($request, $params)));
        //
        // {
        //     "summary" => array(
        //         "totalValue" => "1523.45",
        //         "positionValue" => "523.45",
        //         "walletBalance" => "1000.00",
        //         "totalClaimableAmount" => "50.00",
        //         "todayRealizedPnl" => "15.30",
        //         "todayRealizedPnlPercent" => "3.10",
        //         "todayTotalCost" => "493.55"
        //     ),
        //     "counts" => array(
        //         "ongoingCount" => 3,
        //         "endedCount" => 12,
        //         "pendingClaimCount" => 1
        //     ),
        //     "positions" => array(
        //         {
        //             "positionId" => 1001,
        //             "vendor" => "PREDICT_FUN",
        //             "chainId" => "56",
        //             "tokenId" => "112233",
        //             "collateralSymbol" => "USDT",
        //             "topicType" => "FLAT",
        //             "marketTopicId" => 4229564,
        //             "marketId" => 5567895,
        //             "marketTopicTitle" => "BTC Price 1h Up or Down?",
        //             "marketTitle" => "UP",
        //             "outcomeName" => "YES",
        //             "outcomeIndex" => 0,
        //             "shares" => "1923.07",
        //             "avgPrice" => "0.52",
        //             "totalCost" => "1.00",
        //             "value" => "1.06",
        //             "currentPrice" => "0.55",
        //             "toWin" => "1923.07",
        //             "positionStatus" => "OPEN",
        //             "canClaim" => false,
        //             "endDate" => 1748134800000,
        //             "unrealizedPnl" => "0.06",
        //             "unrealizedPnlPercent" => "6.00",
        //             "realizedPnl" => "0.00",
        //             "pnl" => "0.06",
        //             "createdTime" => 1748131500000,
        //             "updatedTime" => 1748132000000
        //         }
        //     )
        // }
        //
        $data = $this->safe_list($response, 'positions', array());
        $positions = $this->parse_prediction_positions($data);
        if ($outcomes === null) {
            return $positions;
        }
        $filtered = array();
        $positionsLength = count($positions);
        for ($i = 0; $i < $positionsLength; $i++) {
            $position = $positions[$i];
            $positionOutcome = $this->safe_string($position, 'outcome');
            if (($positionOutcome !== null) && (is_array($requestedOutcomeSymbols) && array_key_exists($positionOutcome ?? '', $requestedOutcomeSymbols))) {
                $filtered[] = $position;
            }
        }
        return $filtered;
    }

    public function fetch_position(string $outcome, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_position(...))($outcome, $params);
    }

    private function do_fetch_position(string $outcome, $params = array()) {
        /**
         * fetch data on an open position
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-$wallet-prediction-trading/api/rest-api/position#query-$positions-by-filter
         *
         * @param {string} [$outcome] filter by $outcome
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction position structures](https://docs.ccxt.com/#/?id=prediction-position-structure)
         */
        $request = array();
        $outcomeObj = null;
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
            $market = $this->market($outcomeObj['market']);
            $request['marketTopicId'] = $market['info']['marketTopicId'];
        }
        $wallet = Async\await($this->fetch_wallet('fetchOrders', $params));
        $request['walletAddress'] = $wallet['walletAddress'];
        $response = Async\await($this->sapiPrivateGetPositionFilter($this->extend($request, $params)));
        //
        //
        $positions = $this->safe_list($response, 'positions', array());
        $parsedPositions = $this->parse_prediction_positions($positions);
        $filteredPositions = $this->filter_by_outcome_since_limit($parsedPositions, $outcome, null, null);
        return $this->safe_dict($filteredPositions, 0);
    }

    public function parse_prediction_position(array $position, ?array $outcomeObj = null): array {
        /**
         * @ignore
         * parses a spot balance entry for an $outcome token into a unified $position object
         * @param {array} $position the raw balance entry
         * @param {array} [$outcomeObj] the ourtome the $position belongs to
         * @return {array} a [prediction $position structure](https://docs.ccxt.com/#/?id=prediction-$position-structure)
         */
        if ($outcomeObj === null) {
            $marketId = $this->safe_string($position, 'marketId');
            $outcome = $this->safe_string_upper($position, 'outcomeName');
            $market = $this->safe_market($marketId);
            $outcomeName = $this->safe_string($market, 'market');
            if ($outcomeName === null) {
                $outcomeName = $marketId;
            }
            $outcomeName .= ':' . $outcome;
            $outcomeObj = $this->safe_outcome($outcomeName);
        }
        $timestamp = $this->safe_integer($position, 'createdTime');
        $totalCost = $this->parse_number($this->safe_string($position, 'totalCost'));
        return $this->safe_prediction_position(array(
            'id' => $this->safe_integer($position, 'positionId'),
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string_2($outcomeObj, 'outcomeId', 'id'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'isolated' => false,
            'hedged' => null,
            'side' => 'long',
            'contracts' => null,
            'contractSize' => $this->parse_number($this->safe_string($position, 'shares')),
            'entryPrice' => $this->parse_number($this->safe_string($position, 'avgPrice')),
            'markPrice' => null,
            'notional' => $this->parse_number($this->safe_string($position, 'value')),
            'leverage' => null,
            'collateral' => $totalCost,
            'initialMargin' => $totalCost,
            'maintenanceMargin' => null,
            'initialMarginPercentage' => null,
            'maintenanceMarginPercentage' => null,
            'unrealizedPnl' => $this->parse_number($this->safe_string($position, 'unrealizedPnl')),
            'realizedPnl' => $this->parse_number($this->safe_string($position, 'realizedPnl')),
            'liquidationPrice' => null,
            'marginRatio' => null,
            'marginMode' => 'cross',
            'percentage' => $this->parse_number($this->safe_string($position, 'unrealizedPnlPercent')),
            'info' => $position,
        ));
    }

