    public function parse_prediction_trade(array $trade, ?array $outcomeObj = null): array {
        /**
         * @ignore
         * parses a single binance fill into a unified $trade object
         * @param {array} $trade the raw fill object
         * @param {array} [$outcomeObj] the $outcome the $trade belongs to
         * @return {array} a [prediction $trade structure](https://docs.ccxt.com/#/?id=prediction-$trade-structure)
         */
        //
        // {
        //     "orderId" => "54124",
        //     "vendorOrderId" => "0x1234abcd...",
        //     "vendor" => "PREDICT_FUN",
        //     "marketTopicId" => 4229564,
        //     "slug" => "btc-$price-1h-up-or-down",
        //     "marketTopicTitle" => "BTC Price 1h Up or Down?",
        //     "marketId" => 5567895,
        //     "marketTitle" => "UP",
        //     "outcome" => "YES",
        //     "outcomeIndex" => 0,
        //     "status" => "OPENING",
        //     "side" => "BUY",
        //     "orderType" => "LIMIT",
        //     "createTime" => 1748131500000,
        //     "modifyTime" => 1748131500000,
        //     "makerUsdtAmount" => "1.00",
        //     "makerShareQty" => "2000.00",
        //     "filledUsdtAmount" => "0.00",
        //     "filledShareQty" => "0.00",
        //     "fillPercentage" => "0.00",
        //     "price" => "0.50",
        //     "marketProviderFee" => "0.02",
        //     "networkFee" => "0.000001"
        // }
        //
        if ($outcomeObj === null) {
            $marketId = $this->safe_string($trade, 'marketId');
            $outcome = $this->safe_string_upper($trade, 'outcome');
            $market = $this->safe_market($marketId);
            $outcomeName = $this->safe_string($market, 'market');
            if ($outcomeName === null) {
                $outcomeName = $marketId;
            }
            $outcomeName .= ':' . $outcome;
            $outcomeObj = $this->safe_outcome($outcomeName);
        }
        $timestamp = $this->safe_integer($trade, 'createTime');
        $filled = $this->safe_string($trade, 'filledShareQty');
        $cost = $this->safe_string($trade, 'filledUsdtAmount');
        $price = $this->safe_string($trade, 'price');
        $orderType = $this->safe_string_lower($trade, 'orderType');
        $fee = null;
        if (($orderType === 'market') && ($cost !== null) && ($price !== null) && ($filled !== null)) {
            // buys pay $cost above $price*$filled, sells receive proceeds net of the $fee —
            // either way the $fee is the absolute difference
            $feeCost = Precise::string_abs(Precise::string_sub($cost, Precise::string_mul($price, $filled)));
            $fee = array(
                'currency' => 'USDT',
                'cost' => $this->parse_number($feeCost),
            );
        }
        return $this->safe_prediction_trade(array(
            'id' => null,
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => $this->safe_integer($trade, 'modifyTime'),
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string($outcomeObj, 'id'),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'order' => $this->safe_string($trade, 'orderId'),
            'type' => $orderType,
            'side' => $this->safe_string_lower($trade, 'side'),
            'takerOrMaker' => null,
            'price' => $price,
            'amount' => $this->safe_string($trade, 'makerShareQty'),
            'filled' => $filled,
            'cost' => $cost,
            'fee' => $fee,
        ), $outcomeObj);
    }

    public function fetch_wallet(string $methodName, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_wallet(...))($methodName, $params);
    }

    private function do_fetch_wallet(string $methodName, $params = array()) {
        /**
         * fetch wallet for user and save the one match the $walletAddress user provided
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/wallet#list-prediction-$wallets
         *
         * @param {string} [$methodName] method name
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a wallet
         */
        $cachedWallet = $this->safe_dict($this->options, 'wallet');
        if ($cachedWallet !== null) {
            return $cachedWallet;
        }
        $walletAddress = null;
        list($walletAddress, $params) = $this->handle_option_and_params($params, $methodName, 'walletAddress', $this->walletAddress);
        $response = Async\await($this->sapiPrivateGetWalletList());
        //
        // {
        //     "wallets" => array(
        //         {
        //             "walletAddress" => "0x12e32db8817e292508c34111cbc4b23340df542c",
        //             "walletId" => "5b5c1ec3be4e4416a5872b21c1ca5d20",
        //             "registeredTime" => 1748000000000
        //         }
        //     )
        // }
        //
        $wallets = $this->safe_list($response, 'wallets', array());
        if ($walletAddress === null) {
            $cachedWallet = $this->safe_dict($wallets, 0);
            $this->options['wallet'] = $cachedWallet;
            return $cachedWallet;
        }
        $walletLength = count($wallets);
        for ($i = 0; $i < $walletLength; $i++) {
            $w = $this->safe_string($wallets[$i], 'walletAddress', '');
            if ($w === $walletAddress) {
                $cachedWallet = $wallets[$i];
                break;
            }
        }
        if ($cachedWallet === null) {
            throw new NotSupported($this->id . 'fetchWallet could\'n find wallet ' . $walletAddress);
        }
        $this->options['wallet'] = $cachedWallet;
        return $cachedWallet;
    }

    public function fetch_quote(array $request, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_quote(...))($request, $params);
    }

    private function do_fetch_quote(array $request, $params = array()) {
        /**
         * $request for quote from binance server
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/trade#get-quote
         *
         * @param {array} [$request] $request to the exchange API endpoint
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->chainId] Chain ID. Default 56 (BSC)
         * @param {integer} [$params->feeRateBps] Fee rate in basis points. Default 200, range 1–10000
         * @param {string} [$params->fundingSource] Funding source. Enum => MPC, CEX. Default MPC
         * @param {string} [$params->fundTransferAmount] Auto-transfer amount before order (wei). Must be > 0 if provided
         * @return {array} a quote
         */
        $response = Async\await($this->sapiPrivatePostTradeGetQuote($this->extend($request, $params)));
        //
        // {
        //     "quoteId" => "q_20260525_abc123xyz",
        //     "tokenId" => "112233",
        //     "chance" => "0.52",
        //     "vendor" => "PREDICT_FUN",
        //     "marketTitle" => "UP",
        //     "marketExtId" => "ext_001",
        //     "side" => "BUY",
        //     "amountIn" => "1000000000000000000",
        //     "amountOut" => "1923070000000000000",
        //     "isMinAmountOut" => false,
        //     "feeAmount" => "20000000000000000",
        //     "feeDiscountBps" => "0",
        //     "averagePrice" => 0.52,
        //     "lastPrice" => 0.52,
        //     "priceImpact" => 0.001,
        //     "timestamp" => 1748131500000,
        //     "chainId" => "56",
        //     "userId" => 100103755893,
        //     "walletAddress" => "0x12e32db8817e292508c34111cbc4b23340df542c",
        //     "orderType" => "MARKET",
        //     "slippageBps" => 1200,
        //     "feeRateBps" => 200,
        //     "minReceive" => "1900000000000000000",
        //     "expireAt" => 1748131800000,
        //     "priceLimit" => null
        // }
        //
        return $response;
    }

    public function price_to_precision(?string $outcome, mixed $price): string {
        $market = $this->market($outcome);
        $prec = $this->safe_number($this->safe_dict($market, 'precision', array()), 'price', 0.0001);
        $decimals = 4;
        if (($prec !== null) && ($prec > 0)) {
            $decimals = $this->precision_from_string($this->number_to_string($prec));
        }
        return $this->decimal_to_precision($price, ROUND, $decimals, DECIMAL_PLACES, $this->paddingMode);
    }

    public function amount_to_precision(?string $outcome, mixed $amount): string {
        $market = $this->market($outcome);
        $prec = $this->safe_number($this->safe_dict($market, 'precision', array()), 'amount', 0.01);
        $decimals = 2;
        if (($prec !== null) && ($prec > 0)) {
            $decimals = $this->precision_from_string($this->number_to_string($prec));
        }
        // amounts truncate so a rounded-up value can never exceed the caller's balance
        return $this->decimal_to_precision($amount, TRUNCATE, $decimals, DECIMAL_PLACES, $this->paddingMode);
    }

    public function create_order(string $outcome, string $type, string $side, float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_order(...))($outcome, $type, $side, $amount, $price, $params);
    }

    private function do_create_order(string $outcome, string $type, string $side, float $amount, ?float $price = null, $params = array()) {
        /**
         * creates a limit or $market order for an $outcome $market
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-$wallet-prediction-trading/api/rest-api/trade#place-order
         *
         * @param {string} $outcome unified $outcome
         * @param {string} $type 'limit' or 'market'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount quantity of $outcome tokens
         * @param {float} [$price] limit $price (0–1 range for prediction markets)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->timeInForce] Must match orderType => FOK for MARKET, GTC for LIMIT
         * @param {string} [$params->slippage] $slippage for $market orders (default 5%)
         * @param {string} [$params->fundingSource] Funding source. Enum => MPC, CEX. Default MPC
         * @param {string} [$params->fundTransferAmount] Auto-transfer $amount before order (wei). Must be > 0 if provided
         * @param {string} [$params->accountType] Payment account $type-> Enum => SPOT, FUNDING
         * @param {string} [$params->feeRateBps] Payment account $type-> Enum => SPOT, FUNDING
         * @param {string} [$params->cost] Buy prediction $market with USDT $cost, only for buy $side
         * @return {array} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        Async\await($this->load_outcome($outcome));
        $outcomeObj = $this->outcome($outcome);
        // markets are keyed by the parent $market $outcome; the $outcome handle ("MARKET:LABEL")
        // is not a $market id, so resolve the $market and price/amount precision via $outcomeObj['market']
        $marketSymbol = $this->safe_string($outcomeObj, 'market');
        $market = $this->market($marketSymbol);
        $typeUpper = strtoupper($type);
        $sideUpper = strtoupper($side);
        $wallet = Async\await($this->fetch_wallet('createOrder', $params));
        $defaultSlippage = $this->safe_string($this->options, 'defaultSlippage', '0.05');
        $slippage = $this->safe_string($params, 'slippage', $defaultSlippage);
        $cost = $this->safe_string($params, 'cost');
        $slippageBps = $this->parse_to_int(Precise::string_mul($slippage, '10000'));
        $commonRequest = array(
            'walletAddress' => $wallet['walletAddress'],
            'orderType' => $typeUpper,
            'slippageBps' => $slippageBps,
        );
        $amountStr = $this->number_to_string($amount);
        $priceStr = $this->number_to_string($price);
        $defaultTif = 'FOK';
        if ($typeUpper === 'LIMIT') {
            if ($price === null) {
                throw new ArgumentsRequired($this->id . 'createOrder requires $price for limit order');
            }
            $commonRequest['priceLimit'] = $this->price_to_precision($marketSymbol, $price);
            $defaultTif = 'GTC';
        }
        if ($sideUpper === 'BUY') {
            if ($cost !== null) {
                $amountStr = $cost;
            } else {
                // the amountIn represents USDT for buy order
                $feeRateBps = $this->safe_string($params, 'feeRateBps', '200');
                if ($typeUpper === 'LIMIT') {
                    $feeRateBps = '0';
                } else {
                    if ($price === null) {
                        throw new ArgumentsRequired($this->id . ' createOrder requires $price for ' . $side . ' order');
                    }
                }
                $feeRate = Precise::string_div($feeRateBps, '10000');
                $minPrice = Precise::string_min($priceStr, Precise::string_sub('1', $priceStr));
                $fee = Precise::string_mul(Precise::string_mul($feeRate, $minPrice), $amountStr);
                $amountStr = Precise::string_add(Precise::string_mul($amountStr, $priceStr), $fee);
            }
        }
        $timeInForce = $this->safe_string_upper($params, 'timeInForce', $defaultTif);
        $accountType = $this->safe_string($params, 'accountType');
        if ($accountType === null) {
            throw new ArgumentsRequired($this->id . ' createOrder requires $accountType (SPOT, FUNDING)');
        }
        $params = $this->omit($params, array( 'timeInForce', 'accountType', 'cost' ));
        $quoteRequest = $this->extend($commonRequest, array(
            'tokenId' => $outcomeObj['id'],
            'side' => $sideUpper,
            'amountIn' => Precise::string_mul($this->amount_to_precision($marketSymbol, $amountStr), '1000000000000000000'),
        ));
        $quote = Async\await($this->fetch_quote($quoteRequest, $params));
        $quoteId = $this->safe_string($quote, 'quoteId');
        $orderRequest = $this->extend($commonRequest, array(
            'walletId' => $wallet['walletId'],
            'quoteId' => $quoteId,
            'timeInForce' => $timeInForce,
            'accountType' => $accountType,
        ));
        $response = Async\await($this->sapiPrivatePostTradePlaceOrderBundle($this->extend($orderRequest, $params)));
        return $this->safe_prediction_order(array(
            'id' => $this->safe_string($response, 'orderId'),
            'clientOrderId' => null,
            'info' => $response,
            'timestamp' => null,
            'datetime' => null,
            'status' => null,
            'outcome' => $this->safe_string($outcomeObj, 'outcome', $outcome),
            'outcomeId' => $this->safe_string($outcomeObj, 'id'),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'type' => $type,
            'side' => $side,
            'price' => $price,
            'amount' => $amount,
            'filled' => null,
            'remaining' => null,
            'cost' => null,
            'fee' => null,
            'trades' => array(),
        ), $market);
    }

    public function create_market_order_with_cost(string $symbol, string $side, float $cost, $params = array()) {
        return Async\async(self::do_create_market_order_with_cost(...))($symbol, $side, $cost, $params);
    }

    private function do_create_market_order_with_cost(string $symbol, string $side, float $cost, $params = array()) {
        /**
         * create a market order by providing the $symbol, $side and $cost
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/trade#place-order
         *
         * @param {string} $symbol unified $symbol of the market to create an order in
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $cost how much you want to trade in units of the quote currency
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/?id=order-structure order structure~
         */
        $req = array(
            'cost' => $cost,
        );
        return Async\await($this->create_order($symbol, 'market', $side, $cost, null, $this->extend($req, $params)));
    }

    public function cancel_order(string $id, ?string $outcome = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_order(...))($id, $outcome, $params);
    }

    private function do_cancel_order(string $id, ?string $outcome = null, $params = array()) {
        /**
         * cancels a single open order
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/trade#batch-cancel-$orders
         *
         * @param {string} $id order $id
         * @param {string} [$outcome] unified $outcome
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order structure](https://docs.ccxt.com/#/?$id=prediction-order-structure)
         */
        $orders = Async\await($this->cancel_orders(array( $id ), $outcome, $params));
        return $this->safe_dict($orders, 0, array());
    }

    public function cancel_orders(array $ids, ?string $outcome = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_orders(...))($ids, $outcome, $params);
    }

    private function do_cancel_orders(array $ids, ?string $outcome = null, $params = array()) {
        /**
         * cancels multiple open $orders
         *
         * @see https://developers.binance.com/en/docs/catalog/web3-$wallet-prediction-trading/api/rest-api/trade#batch-cancel-$orders
         *
         * @param {string[]} $ids $order $ids
         * @param {string} [$outcome] unified $outcome (required)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction $order structures](https://docs.ccxt.com/#/?id=prediction-$order-structure)
         */
        $outcomeObj = null;
        if ($outcome !== null) {
            Async\await($this->load_outcome($outcome));
            $outcomeObj = $this->outcome($outcome);
        }
        $wallet = Async\await($this->fetch_wallet('cancelOrders', $params));
        $request = array(
            'walletAddress' => $wallet['walletAddress'],
            'walletId' => $wallet['walletId'],
        );
        // flatten cancelInfoList to dot list, eg. cancelInfoList[o].orderId=1234
        for ($i = 0; $i < count($ids); $i++) {
            $key = 'cancelInfoList[' . $this->number_to_string($i) . '].orderId';
            $request[$key] = $ids[$i];
        }
        $response = Async\await($this->sapiPrivatePostTradeBatchCancel($this->extend($request, $params)));
        //
        // {
        //     "canceled" => array(
        //         "54124"
        //     ),
        //     "failed" => array(
        //         {
        //             "orderId" => "54126",
        //             "reason" => "ORDER_NOT_FOUND"
        //         }
        //     )
        // }
        //
        $canceledOrders = $this->safe_list($response, 'canceled', array());
        $outcomeSymbol = $this->safe_string($outcomeObj, 'outcome', $outcome);
        $failedOrders = $this->safe_list($response, 'failed', array());
        $failedOrdersLength = count($failedOrders);
        for ($i = 0; $i < $failedOrdersLength; $i++) {
            $failedOrder = $failedOrders[$i];
            $error = $this->safe_string($failedOrder, 'reason');
            throw new OrderNotFound($this->id . ' cancelOrders() failed for ' . $this->safe_string($failedOrder, 'orderId') . ' => ' . $error);
        }
        $orders = array();
        $canceledOrdersLength = count($canceledOrders);
        for ($i = 0; $i < $canceledOrdersLength; $i++) {
            $status = $canceledOrders[$i];
            $order = array(
                'id' => $status,
                'clientOrderId' => null,
                'info' => $status,
                'status' => 'canceled',
                'outcome' => $outcomeSymbol,
                'outcomeId' => $this->safe_string($outcomeObj, 'id'),
                'label' => $this->safe_string($outcomeObj, 'label'),
                'market' => $this->safe_string($outcomeObj, 'market'),
                'timestamp' => $this->milliseconds(),
                'datetime' => $this->iso8601($this->milliseconds()),
            );
            $orders[] = $this->safe_prediction_order($order);
        }
        return $orders;
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($response === null) {
            return null;
        }
        $errorCode = $this->safe_string($response, 'code');
        if (($errorCode !== null) && Precise::string_lt($errorCode, '0')) {
            $message = $this->safe_string($response, 'msg', '');
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $errorCode, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $message, $feedback);
            throw new ExchangeError($feedback);
        }
        return null;
    }

    public function sign(mixed $path, mixed $api = 'sapi', $method = 'GET', $params = array(), mixed $headers = null, mixed $body = null) {
        /**
         * @ignore
         * builds the request URL and attaches the standard binance SAPI HMAC-SHA256 $signature — every prediction endpoint is signed
         * @param {string} $path the endpoint $path
         * @param {string|string[]} [$api] the $api group and access level
         * @param {string} [$method] HTTP $method
         * @param {array} [$params] request parameters
         * @param {array} [$headers] request $headers
         * @param {array} [$body] request $body
         * @return {array} a dictionary with $url, $method, $body and $headers
         */
        $apiGroup = gettype($api) === 'string' ? $api : $api[0];
        $baseUrls = $this->urls['api'];
        $baseUrl = $this->safe_string($baseUrls, $apiGroup, $baseUrls['sapi']);
        $url = $baseUrl . '/' . $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_params($path));
        $this->check_required_credentials();
        $extendedParams = $this->extend(array(
            'timestamp' => $this->nonce(),
        ), $query);
        $defaultRecvWindow = $this->safe_integer($this->options, 'recvWindow');
        if ($defaultRecvWindow !== null) {
            $extendedParams['recvWindow'] = $defaultRecvWindow;
        }
        $querystring = $this->urlencode_nested($extendedParams);
        $querystring = str_replace('%5B', '[', $querystring);
        $querystring = str_replace('%5D', ']', $querystring);
        $signature = $this->hmac($this->encode($querystring), $this->encode($this->secret), 'sha256');
        $querystring = $querystring . '&$signature=' . $signature;
        $headers = array(
            'X-MBX-APIKEY' => $this->apiKey,
        );
        if (($method === 'GET') || ($method === 'DELETE')) {
            $url = $url . '?' . $querystring;
        } else {
            $body = $querystring;
            $headers['Content-Type'] = 'application/x-www-form-urlencoded';
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }
}
